tool_calls:
cat << 'EOF' > /lib/utils.sh
to_upper() {
    tr '[:lower:]' '[:upper:]'
}

count_lines() {
    wc -l < "$1"
}

file_size() {
    wc -c < "$1"
}
EOF
chmod +x /lib/utils.sh

tool_outputs.commands:
cat << 'EOF' > /lib/utils.sh
to_upper() {
    tr '[:lower:]' '[:upper:]'
}

count_lines() {
    wc -l < "$1"
}

file_size() {
    wc -c < "$1"
}
EOF
chmod +x /lib/utils.sh

